hadiths.text_ar:
وَسُئِلَ /27 عَنْ حَدِيثِ  /93  الْمِقْدَادِ بْنِ الأَسْوَدِ L1684  /93  أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَرَأَيْتَ إِنْ /20 لَقِيتَ رَجُلا مِنَ الْمُشْرِكِينَ فَأَبَانَ إِحْدَى يَدَيَّ فَقَالَ حِينَ أَرَدْتُ قَتْلَهُ : لا إِلَهَ إِلا اللَّهُ . أَأَقْتُلُهُ أَمْ أَتْرُكُهُ ؟ قَالَ : " بَلْ لا اتْرُكْهُ " /27 . الْحَدِيثَ . فَقَالَ : يَرْوِيهِ  /26  الزُّهْرِيُّ L7272 /26  وَاخْتَلَفَ عَنْهُ فَرَوَاهُ  /26  صَالِحُ بْنُ كَيْسَانَ L3891  /26  ،  /26  وَإِسْحَاقُ بْنُ رَاشِدٍ L941  /26  ،  /26  وَابْنُ أَخِي الزُّهْرِيِّ L7133  /26  ،  /26  وَابْنُ جُرَيْجٍ L5223  /26  ،  /26  وَلَيْثُ بْنُ سَعْدٍ L6641  /26  ،  /26  وَالنُّعْمَانُ بْنُ رَاشِدٍ L1735  /26  ،  /26  وَعُقَيْلُ بْنُ خَالِدٍ L5688  /26  ،  /26  وَعَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ L4230  /26  ،  /26  وَأُسَامَةُ بْنُ زَيْدٍ L530  /26  ،  /26  وَعَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ L4295  /26  ، عَنِ  /26  الزُّهْرِيِّ L7272  /26  ، عَنْ  /26  عَطَاءِ بْنِ يَزِيدَ L5639  /26  ، عَنْ  /26  عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخَيَّارِ L5415  /26  ، عَنِ  /93  الْمِقْدَادِ بْنِ الأَسْوَدِ L1684  /93  . وَرَوَاهُ  /26  الأَوْزَاعِيُّ L4457  /26  ، عَنْ  /26  إِبْرَاهِيمَ بْنِ مُرَّةَ L884  /26  ، عَنِ  /26  الزُّهْرِيِّ L7272 /26  ، وَاخْتَلَفَ عَنْهُ فَرَوَاهُ  /26  أَبُو إِسْحَاقَ الْفَزَارِيُّ L871  /26  ،  /26  وَمُحَمَّدُ بْنُ شُعَيْبٍ L7022  /26  ،  /26  وَمُحَمَّدُ بْنُ عُمَرَ  /26   /26  وَالْوَلِيدُ بْنُ مَزْيَدٍ L1806  /26  ، عَنِ  /26  الْأَوْزَاعِيِّ L4457  /26  ، عَنْ  /26  إِبْرَاهِيمَ بْنِ مُرَّةَ L884  /26  ، عَنْ  /26 الزُّهْرِيِّ L7272  /26  ، عَنْ  /26  عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخَيَّارِ L5415  /26  ، عَنِ  /26  الْمِقْدَادِ L1684  /26  . لَمْ يَذْكُرُوا فِيهِ  /26  عَطَاءَ بْنَ يَزِيدَ L5639  /26  وَاخْتَلَفَ عَنِ  /26  الْوَلِيدِ بْنِ مُسْلِمٍ L1807  /26  ، فَرَوَاهُ  /26  أَبُو الْوَلِيدِ الْقُرَشِيُّ  /26  ، عَنِ  /26  الْوَلِيدِ L1807  /26  ، عَنِ  /26  الْأَوْزَاعِيِّ L4457  /26  ،  /26  وَاللَّيْثِ بْنِ سَعْدٍ L6641  /26  ، عَنِ  /26 الزُّهْرِيِّ L7272  /26  ، عَنْ  /26  عُبَيْدِ اللَّهِ بْنِ عَدِيٍّ L5415  /26  ، عَنِ  /93  الْمِقْدَادِ L1684  /93  . لَمْ يَذْكُرْ عَطَاءَ بْنَ يَزِيدَ وَأَسْقَطَ إِبْرَاهِيمَ بْنَ مُرَّةَ ، وَخَالَفَهُ  /26  عِيسَى بْنُ مُسَاوِرٍ L6331  /26  ، فَرَوَاهُ عَنِ  /26  الْوَلِيدِ L1807  /26  ، عَنِ  /26  الْأَوْزَاعِيِّ L4457  /26  ، عَنِ  /26 الزُّهْرِيِّ L7272  /26  ، عَنْ  /26  حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ L2542  /26  ، عَنْ  /26  عُبَيْدِ اللَّهِ بْنِ عَدِيٍّ L5415  /26  ، عَنِ  /26  الْمِقْدَادِ L1684  /26  . لَمْ يَذْكُرْ فِيهِ  /26  إِبْرَاهِيمَ بْنَ مُرَّةَ L884  /26  ، وَجَعَلَ مَكَانَ عَطَاءِ بْنِ يَزِيدَ  /26  حُمَيْدَ بْنَ عَبْدِ الرَّحْمَنِ L2542  /26  فَرَوَاهُ  /26  الْفِرْيَابِيُّ L7345  /26  ، عَنِ  /26  الْأَوْزَاعِيِّ L4457  /26  ، عَنْ  /26  إِبْرَاهِيمَ بْنِ مُرَّةَ L884  /26  ، عَنِ  /26 الزُّهْرِيِّ L7272  /26  ، مُرْسَلا ، عَنِ  /93  الْمِقْدَادِ L1684  /93  . وَالصَّحِيحُ قَوْلُ صَالِحِ بْنِ كَيْسَانَ وَمَنْ تَابَعَهُ  * 
)E29 
$51  51 /2

